CREATE OR REPLACE FUNCTION generate_performance_alert()
RETURNS TRIGGER AS $$
DECLARE
    v_panel_powratew SMALLINT;
    v_plant_initdate DATE;
    v_years_old NUMERIC;
    v_expected_ppr NUMERIC;
    v_actual_ppr NUMERIC;
    v_cumdeg NUMERIC;
    v_critical_threshold NUMERIC;
    v_existing_alert_id VARCHAR;
    v_replace_prior VARCHAR;
    v_alert_hash VARCHAR;
BEGIN
    -- Get panel rated power
    SELECT powratew INTO v_panel_powratew
    FROM panel
    WHERE panemark = NEW.solmodref;

    -- Get plant initdate
    SELECT p.initdate INTO v_plant_initdate
    FROM panel pn
    JOIN plant p ON pn.hubregistry = p.growregistry
    WHERE pn.panemark = NEW.solmodref;

    -- Calculate years since plant inception
    v_years_old := EXTRACT(YEAR FROM AGE(COALESCE(NEW.perfmoment, NOW()), v_plant_initdate));

    -- Cumulative degradation percentage (using 0.7% per year as baseline)
    v_cumdeg := v_years_old * 0.7;

    -- Expected PPR accounting for degradation (base is 100%)
    v_expected_ppr := 100.0 - v_cumdeg;

    -- Actual PPR = measured power / rated power * 100
    v_actual_ppr := (NEW.measpoww::NUMERIC / v_panel_powratew::NUMERIC) * 100.0;

    -- Critical threshold: 80% of expected value
    v_critical_threshold := v_expected_ppr * 0.8;

    -- Check if performance is below critical threshold
    IF v_actual_ppr < v_critical_threshold THEN
        -- Determine replacement priority
        IF v_actual_ppr < (v_expected_ppr * 0.6) THEN
            v_replace_prior := 'High';
        ELSE
            v_replace_prior := 'Medium';
        END IF;

        -- Generate a hash for the alert ID
        v_alert_hash := LEFT(MD5(NEW.perfregistry || NEW.solmodref || NEW.perfmoment::TEXT), 8);

        -- Check for existing alert within 30-day window
        SELECT alertreg INTO v_existing_alert_id
        FROM alerts
        WHERE deviceref = NEW.solmodref
          AND incidentref = NEW.perfregistry
          AND alertmoment >= (COALESCE(NEW.perfmoment, NOW()) - INTERVAL '30 days')
        LIMIT 1;

        IF v_existing_alert_id IS NOT NULL THEN
            -- Update existing alert
            UPDATE alerts
            SET alertstat = 'Critical',
                maintprior = 'High',
                replaceprior = v_replace_prior,
                optpotential = 'High',
                alertcnt = alertcnt + 1,
                alertmoment = COALESCE(NEW.perfmoment, NOW())
            WHERE alertreg = v_existing_alert_id;
        ELSE
            -- Insert new alert
            INSERT INTO alerts (alertreg, compreg, deviceref, incidentref, alertmoment, alertstat, alertcnt, maintprior, replaceprior, optpotential)
            VALUES (
                'ALERT_' || v_alert_hash,
                (SELECT hubregistry FROM panel WHERE panemark = NEW.solmodref),
                NEW.solmodref,
                NEW.perfregistry,
                COALESCE(NEW.perfmoment, NOW()),
                'Critical',
                1,
                'High',
                v_replace_prior,
                'High'
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

